/**
 * M-A0 gate 5 (iteration-tied interner lifetime) at the compiled-step boundary: one compiled native group step whose
 * group key is a computed, runtime-interned value (a {@code COALESCE(STR(?o), ...)} string too long for an inline id)
 * must be evaluable repeatedly with identical results, and after its result iterations are closed the compiled-plan
 * state must retain no runtime-interned values. Runtime interning belongs to the evaluation (a
 * {@link NativeExecutionContext}), never to compiled-plan state, because a compiled step outlives its evaluations and
 * may serve them concurrently.
 */
public class LmdbNativeRuntimeInternerLifetimeTest {

	private static final String EX = "http://example.com/";

	/** Long local names so STR(?o) can never be packed into an inline id and must be interned at runtime. */
	private static final String LONG_SUFFIX = "-object-with-a-deliberately-long-local-name-beyond-inline-packing";

	private static final String QUERY = "SELECT ?key (COUNT(*) AS ?count) WHERE {\n"
			+ "  ?s <" + EX + "link> ?o .\n"
			+ "  BIND(COALESCE(STR(?o), \"fallback\") AS ?key)\n"
			+ "} GROUP BY ?key";

	private static final CloseableIteration<Statement> EMPTY_ITERATION = new CloseableIteration<>() {
		@Override
		public boolean hasNext() {
			return false;
		}

		@Override
		public Statement next() {
			throw new NoSuchElementException();
		}

		@Override
		public void remove() {
			throw new UnsupportedOperationException();
		}

		@Override
		public void close() {
		}
	};

	@TempDir
	File dataDir;

	private LmdbStore store;
	private SailRepository repository;
	private SailDataset dataset;

	@BeforeEach
	public void setUp() {
		store = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc,ospc"));
		repository = new SailRepository(store);
		try (SailRepositoryConnection conn = repository.getConnection()) {
			ValueFactory vf = conn.getValueFactory();
			IRI link = vf.createIRI(EX, "link");
			conn.begin();
			for (int i = 0; i < 20; i++) {
				IRI s = vf.createIRI(EX, "s" + i);
				IRI o = vf.createIRI(EX, "o" + (i % 4) + LONG_SUFFIX);
				conn.add(s, link, o);
			}
			conn.commit();
		}
		dataset = NativeQuerySourceAccess.openExplicitDataset(store);
	}

	@AfterEach
	public void tearDown() {
		if (dataset != null) {
			dataset.close();
		}
		if (repository != null) {
			repository.shutDown();
		}
	}

	@Test
	public void compiledGroupStepRetainsNoInternerStateAfterEvaluationsClose() throws Exception {
		Group group = parseGroup();
		LmdbNativeEvaluationStrategy strategy = new LmdbNativeEvaluationStrategy(new EmptyTripleSource(), null, null,
				0L, new EvaluationStatistics(), false);
		QueryEvaluationStep step = LmdbNativeAggregateCompiler.tryCompile(group,
				new QueryEvaluationContext.Minimal((Dataset) null), strategy, (NativeLmdbQuerySource) dataset);
		assertThat(step)
				.as("the computed-group-key aggregate must compile natively (precondition for this lifetime test)")
				.isInstanceOf(NativeGroupStep.class);

		List<String> first = drain(step);
		List<String> second = drain(step);

		assertThat(first)
				.as("the computed STR group keys must actually flow through the runtime interner")
				.hasSize(4)
				.allSatisfy(row -> assertThat(row).contains(EX + "o"));
		assertThat(second)
				.as("a compiled step evaluated twice must return identical results")
				.isEqualTo(first);

		NativeLmdbQuerySource compiledSource = ((NativeGroupStep) step).source;
		assertThat(retainedMapEntries(compiledSource))
				.as("compiled-plan state must retain no runtime-interned values once evaluations are closed "
						+ "(runtime interning belongs to the per-evaluation NativeExecutionContext)")
				.isZero();
	}

	private Group parseGroup() {
		TupleExpr parsed = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, QUERY, null).getTupleExpr();
		List<Group> groups = new ArrayList<>();
		parsed.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Group node) {
				groups.add(node);
				super.meet(node);
			}
		});
		assertThat(groups).as("the query must parse to exactly one Group").hasSize(1);
		return groups.get(0);
	}

	private static List<String> drain(QueryEvaluationStep step) {
		List<String> rows = new ArrayList<>();
		try (CloseableIteration<BindingSet> iteration = step.evaluate(EmptyBindingSet.getInstance())) {
			while (iteration.hasNext()) {
				BindingSet row = iteration.next();
				rows.add(row.getValue("key").stringValue() + "=" + ((Literal) row.getValue("count")).longValue());
			}
		}
		Collections.sort(rows);
		return rows;
	}

	/**
	 * Total entries across every {@link Map}-typed field of the compiled step's retained source object. The scan is
	 * shape-agnostic on purpose: whatever class holds the compiled step's value-source state, compiled-plan state
	 * retaining zero map entries after close is the contract under pin.
	 */
	private static int retainedMapEntries(Object source) throws Exception {
		int total = 0;
		for (Class<?> type = source.getClass(); type != null; type = type.getSuperclass()) {
			for (Field field : type.getDeclaredFields()) {
				if (Map.class.isAssignableFrom(field.getType())) {
					field.setAccessible(true);
					Map<?, ?> map = (Map<?, ?>) field.get(source);
					if (map != null) {
						total += map.size();
					}
				}
			}
		}
		return total;
	}

	private static final class EmptyTripleSource implements TripleSource {

		@Override
		public CloseableIteration<? extends Statement> getStatements(Resource subj, IRI pred, Value obj,
				Resource... contexts) {
			return EMPTY_ITERATION;
		}

		@Override
		public ValueFactory getValueFactory() {
			return SimpleValueFactory.getInstance();
		}
	}
}
